WITH filtered AS (SELECT *, SUBSTRING(channel, 1, 2) AS channel_prefix, CAST(discount_pct AS INT) AS discount_pct_int, COALESCE(channel, 'OTHER') AS channel_clean FROM promotions WHERE ends_on >= TO_DATE('2023-08-10') AND channel IS NOT NULL AND discount_pct <= 0.22) SELECT *, ROW_NUMBER() OVER (PARTITION BY promo_code ORDER BY discount_pct_int DESC, id ASC) AS row_seq, ROUND(discount_pct / SUM(discount_pct) OVER (PARTITION BY channel), 4) AS discount_pct_share FROM filtered
